% mathsmap-diagram-colours {"version":1,"kind":"geometry","base":[],"semantic":[],"reference":"source page 1 p1-arrays-complete-solution"}
\begin{tikzpicture}[x=2mm,y=2mm,text=black,every node/.style={font=\fontsize{10}{12}\selectfont}]
\special{dvisvgm:raw <metadata data-graph-strokes="1"/>}
\foreach \n/\k in {1/0,2/1,3/2,4/3,5/4,6/5,7/6,8/7,9/8,10/9,11/10,12/11,13/12,14/13,15/14,16/15,17/16,18/17,19/18,20/19}{
\pgfmathtruncatemacro{\panel}{floor(\k/10)}
\pgfmathtruncatemacro{\row}{mod(\k,10)}
\begin{scope}[shift={(60*\panel,-12*\row)}]
\node[anchor=east] at (-1,0) {\n};
\foreach \r in {1,...,4}{
\pgfmathtruncatemacro{\rem}{mod(\n,\r)}
\pgfmathtruncatemacro{\c}{\n/\r}
\ifnum\rem=0
\ifnum\r>\c\else
\pgfmathsetmacro{\offset}{ifthenelse(\r==1,0,ifthenelse(\r==2,22,40))}
\foreach \i in {1,...,\r}{\foreach \j in {1,...,\c}{\fill[black] (\offset+\j-1,1-\i) circle[radius=0.3];}}
\node[anchor=north] at ({\offset+(\c-1)/2},{-\r-0.5}) {$\r\times\c$};
\fi\fi
}
\end{scope}}
\end{tikzpicture}
